func TestAuthOAuthLoginRejectsMalformedCallback(t *testing.T) {
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("reserve port: %v", err)
	}
	redirectURI := "http://" + listener.Addr().String() + "/callback"
	_ = listener.Close()

	oldOpen := openOAuthBrowser
	openOAuthBrowser = func(raw string) error {
		parsed, err := url.Parse(raw)
		if err != nil {
			return err
		}
		state := parsed.Query().Get("state")
		go func() {
			callbackURL := redirectURI + "?state=" + url.QueryEscape(state)
			for range 50 {
				wrongStateURL := redirectURI + "?state=wrong"
				wrongResp, wrongErr := http.Get(wrongStateURL) //nolint:gosec // loopback test callback
				if wrongErr == nil {
					_ = wrongResp.Body.Close()
				}
				req, reqErr := http.NewRequest(http.MethodPost, callbackURL, nil)
				if reqErr != nil {
					return
				}
				resp, doErr := http.DefaultClient.Do(req) //nolint:gosec // loopback test callback
				if doErr == nil {
					_ = resp.Body.Close()
					resp, doErr = http.Get(callbackURL) //nolint:gosec // loopback test callback
					if doErr == nil {
						_ = resp.Body.Close()
					}
					return
				}
				time.Sleep(10 * time.Millisecond)
			}
		}()
		return nil
	}
	t.Cleanup(func() { openOAuthBrowser = oldOpen })

	ctx, _, _ := testutil.NewTestContext(t, output.FormatPlain)
	ctx.ConfigPath = filepath.Join(t.TempDir(), "config.toml")
	ctx.ProfileKey = "default"
	err = (&AuthOAuthLoginCmd{
		ClientID:    "client-id",
		RedirectURI: redirectURI,
		WaitTimeout: time.Second,
	}).Run(ctx)
	if err == nil || !strings.Contains(err.Error(), "missing the authorization code") {
		t.Fatalf("expected missing code error, got %v", err)
	}
}

package spotify

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"time"

	"github.com/steipete/spogo/internal/atomicfile"
)

type OAuthTokenStatus struct {
	Exists     bool
	ClientID   string
	Scopes     []string
	ExpiresAt  time.Time
	Expired    bool
	HasRefresh bool
	FileMode   os.FileMode
}

func LoadOAuthToken(path string) (OAuthToken, error) {
	if _, err := os.Stat(path); err != nil {
		return OAuthToken{}, err
	}
	cacheLock, err := acquireOAuthCacheLock(context.Background(), path)
	if err != nil {
		return OAuthToken{}, err
	}
	defer releaseOAuthCacheLock(cacheLock)
	return loadOAuthTokenUnlocked(path)
}

func loadOAuthTokenUnlocked(path string) (OAuthToken, error) {
	info, err := os.Stat(path)
	if err != nil {
		return OAuthToken{}, err
	}
	if runtime.GOOS != "windows" {
		dirInfo, err := os.Stat(filepath.Dir(path))
		if err != nil {
			return OAuthToken{}, err
		}
		if dirInfo.Mode().Perm()&0o077 != 0 {
			return OAuthToken{}, fmt.Errorf("oauth token cache directory permissions are %04o; require 0700", dirInfo.Mode().Perm())
		}
	}
	if !info.Mode().IsRegular() {
		return OAuthToken{}, errors.New("oauth token cache is not a regular file")
	}
	if runtime.GOOS != "windows" && info.Mode().Perm()&0o077 != 0 {
		return OAuthToken{}, fmt.Errorf("oauth token cache permissions are %04o; require 0600", info.Mode().Perm())
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return OAuthToken{}, err
	}
	var token OAuthToken
	if err := json.Unmarshal(data, &token); err != nil {
		return OAuthToken{}, fmt.Errorf("decode oauth token cache: %w", err)
	}
	if token.RefreshToken == "" && token.AccessToken == "" {
		return OAuthToken{}, errors.New("oauth token cache contains no tokens")
	}
	return token, nil
}

func SaveOAuthToken(path string, token OAuthToken) error {
	cacheLock, err := acquireOAuthCacheLock(context.Background(), path)
	if err != nil {
		return err
	}
	defer releaseOAuthCacheLock(cacheLock)
	return saveOAuthTokenUnlocked(path, token)
}

func saveOAuthTokenUnlocked(path string, token OAuthToken) error {
	if path == "" {
		return errors.New("oauth token cache path is required")
	}
	if token.RefreshToken == "" {
		return errors.New("refusing to cache oauth token without refresh token")
	}
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	if runtime.GOOS != "windows" {
		if err := os.Chmod(dir, 0o700); err != nil {
			return err
		}
	}
	data, err := json.MarshalIndent(token, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	return atomicfile.Write(path, data)
}

func OAuthStatus(path string) (OAuthTokenStatus, error) {
	if _, err := os.Stat(path); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return OAuthTokenStatus{}, nil
		}
		return OAuthTokenStatus{}, err
	}
	cacheLock, err := acquireOAuthCacheLock(context.Background(), path)
	if err != nil {
		return OAuthTokenStatus{}, err
	}
	defer releaseOAuthCacheLock(cacheLock)
	info, err := os.Stat(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return OAuthTokenStatus{}, nil
		}
		return OAuthTokenStatus{}, err
	}
	token, err := loadOAuthTokenUnlocked(path)
	if err != nil {
		return OAuthTokenStatus{}, err
	}
	scopes := strings.Fields(token.Scope)
	return OAuthTokenStatus{
		Exists:     true,
		ClientID:   token.ClientID,
		Scopes:     scopes,
		ExpiresAt:  token.ExpiresAt,
		Expired:    !token.ExpiresAt.IsZero() && !token.ExpiresAt.After(time.Now()),
		HasRefresh: token.RefreshToken != "",
		FileMode:   info.Mode().Perm(),
	}, nil
}

func ClearOAuthToken(path string) error {
	if path == "" {
		return errors.New("oauth token cache path is required")
	}
	cacheLock, err := acquireOAuthCacheLock(context.Background(), path)
	if err != nil {
		return err
	}
	defer releaseOAuthCacheLock(cacheLock)
	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

