func TestSearchDocumentedResponse(t *testing.T) {
	// Synthetic catalog data using Spotify's documented search response shape:
	// https://developer.spotify.com/documentation/web-api/reference/search
	fixture, err := os.ReadFile("testdata/search_response.json")
	if err != nil {
		t.Fatal(err)
	}
	for _, kind := range []string{"track", "album", "artist", "playlist", "show", "episode"} {
		for _, engine := range []string{"web", "connect-web-fallback"} {
			t.Run(kind+"/"+engine, func(t *testing.T) {
				transport := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
					if req.Method != http.MethodGet || req.URL.Path != "/v1/search" {
						t.Errorf("unexpected request: %s %s", req.Method, req.URL.Path)
					}
					params := req.URL.Query()
					if params.Get("type") != kind || params.Get("q") != "fixture" || params.Get("limit") != "1" || params.Get("offset") != "1" {
						t.Errorf("unexpected search parameters: %v", params)
					}
					return &http.Response{
						StatusCode:    http.StatusOK,
						Header:        http.Header{"Content-Type": []string{"application/json"}},
						ContentLength: int64(len(fixture)),
						Body:          io.NopCloser(bytes.NewReader(fixture)),
					}, nil
				})
				client, err := NewClient(Options{
					TokenProvider: staticTokenProvider{},
					HTTPClient:    &http.Client{Transport: transport},
				})
				if err != nil {
					t.Fatal(err)
				}
				search := client.Search
				if engine == "connect-web-fallback" {
					search = newConnectClientForTests(transport).searchViaWebAPI
				}
				result, err := search(context.Background(), kind, "fixture", 1, 1)
				if err != nil {
					t.Fatalf("search: %v", err)
				}
				if result.Type != kind || result.Limit != 1 || result.Offset != 1 || result.Total != 3 {
					t.Errorf("unexpected result metadata: %#v", result)
				}
				if len(result.Items) != 1 {
					t.Fatalf("expected one item, got %d", len(result.Items))
				}
				item := result.Items[0]
				if item.Type != kind || item.ID != kind+"1" || item.Name != "Fixture "+kind || item.URI != "spotify:"+kind+":"+kind+"1" {
					t.Errorf("unexpected item: %#v", item)
				}
				if kind == "track" && (item.Album != "Fixture album" || len(item.Artists) != 1 || item.Artists[0] != "Fixture artist" || item.DurationMS != 123000) {
					t.Errorf("unexpected track metadata: %#v", item)
				}
			})
		}
	}
}

package spotify

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

type countingTokenProvider struct {
	calls int
}

func (p *countingTokenProvider) Token(context.Context) (Token, error) {
	p.calls++
	return Token{AccessToken: "token", ExpiresAt: time.Now().Add(time.Hour)}, nil
}

func TestClientRetriesOnRateLimit(t *testing.T) {
	provider := &countingTokenProvider{}
	requests := 0
	mux := http.NewServeMux()
	mux.HandleFunc("/me/player/devices", func(w http.ResponseWriter, r *http.Request) {
		requests++
		if requests == 1 {
			w.Header().Set("Retry-After", "0")
			w.WriteHeader(http.StatusTooManyRequests)
			_ = json.NewEncoder(w).Encode(map[string]any{
				"error": map[string]any{
					"status":  http.StatusTooManyRequests,
					"message": "rate limit",
				},
			})
			return
		}
		_ = json.NewEncoder(w).Encode(deviceResponse{Devices: []deviceItem{{ID: "d1", Name: "Desk"}}})
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	client, err := NewClient(Options{
		TokenProvider: provider,
		BaseURL:       srv.URL,
		HTTPClient:    srv.Client(),
	})
	if err != nil {
		t.Fatalf("client: %v", err)
	}

	if _, err := client.Devices(context.Background()); err != nil {
		t.Fatalf("devices: %v", err)
	}
	if requests != 2 {
		t.Fatalf("expected 2 requests, got %d", requests)
	}
	if provider.calls != 1 {
		t.Fatalf("rate limits must retain the valid token, got %d provider calls", provider.calls)
	}
}

// TestClientRetriesRateLimitedMutationAndSurfacesRetryAfter proves the default
// retry policy is unchanged: a mutating request (PUT /me/player/play) is still
// retried across all attempts on repeated 429s, and the final surfaced error
// carries the Retry-After from the last response so callers can see the
// cooldown hint. The hint is Spotify's earliest-retry guidance, not a
// guarantee that waiting it out clears the rate limit.
func TestClientRetriesRateLimitedMutationAndSurfacesRetryAfter(t *testing.T) {
	provider := &countingTokenProvider{}
	requests := 0
	mux := http.NewServeMux()
	mux.HandleFunc("/me/player/play", func(w http.ResponseWriter, r *http.Request) {
		requests++
		// Non-final attempts advertise a short cooldown to keep the retry
		// delay small; the final attempt advertises the real cooldown that
		// must be surfaced to the caller.
		if requests < 3 {
			w.Header().Set("Retry-After", "1")
		} else {
			w.Header().Set("Retry-After", "42")
		}
		w.WriteHeader(http.StatusTooManyRequests)
		_ = json.NewEncoder(w).Encode(map[string]any{
			"error": map[string]any{
				"status":  http.StatusTooManyRequests,
				"message": "rate limit",
			},
		})
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	client, err := NewClient(Options{
		TokenProvider: provider,
		BaseURL:       srv.URL,
		HTTPClient:    srv.Client(),
	})
	if err != nil {
		t.Fatalf("client: %v", err)
	}

	err = client.Play(context.Background(), "spotify:track:t1")
	if err == nil {
		t.Fatalf("expected rate limit error")
	}
	// Default policy retries all methods across the full 3 attempts.
	if requests != 3 {
		t.Fatalf("expected 3 requests, got %d", requests)
	}
	var apiErr APIError
	if !errors.As(err, &apiErr) {
		t.Fatalf("expected APIError, got %T", err)
	}
	if apiErr.Status != http.StatusTooManyRequests {
		t.Fatalf("status = %d, want 429", apiErr.Status)
	}
	if apiErr.RetryAfter != 42*time.Second {
		t.Fatalf("retry after = %v, want 42s", apiErr.RetryAfter)
	}
	if !strings.Contains(apiErr.Error(), "retry-after hint 42s") {
		t.Fatalf("expected retry-after hint in error string, got %q", apiErr.Error())
	}
}

func TestClientReturnsLongCooldownWithoutRetrying(t *testing.T) {
	for _, header := range []string{"120", time.Now().Add(2 * time.Minute).UTC().Format(http.TimeFormat)} {
		t.Run(header, func(t *testing.T) {
			provider := &countingTokenProvider{}
			requests := 0
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				requests++
				w.Header().Set("Retry-After", header)
				w.WriteHeader(http.StatusTooManyRequests)
			}))
			defer server.Close()
			client, err := NewClient(Options{TokenProvider: provider, BaseURL: server.URL, HTTPClient: server.Client()})
			if err != nil {
				t.Fatal(err)
			}
			ctx, cancel := context.WithTimeout(context.Background(), time.Second)
			defer cancel()
			_, err = client.Devices(ctx)
			var apiErr APIError
			if !errors.As(err, &apiErr) || apiErr.Status != 429 || apiErr.RetryAfter < time.Minute {
				t.Fatalf("expected original cooldown, got %v", err)
			}
			if requests != 1 || provider.calls != 1 {
				t.Fatalf("requests=%d, token calls=%d, want 1 each", requests, provider.calls)
			}
		})
	}
}

