						"name": "Track One",
						"artists": []any{
							map[string]any{"name": "Artist"},
						},
					},
				},
				"bad-item",
				map[string]any{"data": map[string]any{}},
			},
		},
	}

	tracks := extractRecentlyPlayedTracks(payload)
